SELECT reconciliation_key FROM (
  SELECT reconciliation_key FROM rpt_payment_fact_inbox WHERE tenant_id=#{tenantId}
    AND business_date BETWEEN #{fromDate} AND #{toDate}
  UNION
  SELECT reconciliation_key FROM rpt_internal_bill_inbox WHERE tenant_id=#{tenantId}
    AND business_date BETWEEN #{fromDate} AND #{toDate}
) keys_ordered ORDER BY reconciliation_key

SELECT  FROM rpt_payment_reconciliation
WHERE tenant_id=#{tenantId} AND business_date BETWEEN #{fromDate} AND #{toDate} AND store_id=#{storeId}
AND difference_type=#{differenceType}
AND handling_state=#{handlingState}
ORDER BY business_date,reconciliation_id

SELECT COUNT(*) FROM rpt_payment_reconciliation WHERE tenant_id=#{tenantId}
  AND business_date BETWEEN #{fromDate} AND #{toDate}
  AND store_id IN
  #{storeId}

SELECT  FROM rpt_payment_reconciliation
WHERE tenant_id=#{tenantId} AND business_date BETWEEN #{fromDate} AND #{toDate}
ORDER BY business_date,reconciliation_id
